package auth

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
	"unsafe"
)

const (
	StateOpen     = 0
	StateHalfOpen = 1
	StateClosed   = 2

	maxFailures    = 5
	resetTimeout   = 30 * time.Second
	tokenLength    = 32
	maxPoolSize    = 64
)

type TokenEntry struct {
	Token     []byte
	UserID    string
	CreatedAt time.Time
	ExpiresAt time.Time
}

type CircuitBreaker struct {
	state        int32
	failureCount int32
	lastFailure  time.Time
	mu           sync.RWMutex
}

type AuthService struct {
	circuitBreaker *CircuitBreaker
	tokenPool      sync.Pool
	activeTokens   sync.Map
	auditLog       []auditEntry
	auditMu        sync.Mutex
	secretKey      []byte
}

type auditEntry struct {
	Timestamp time.Time
	Action    string
	Details   string
}

func NewAuthService(secretKey []byte) *AuthService {
	keyCopy := make([]byte, len(secretKey))
	copy(keyCopy, secretKey)

	as := &AuthService{
		circuitBreaker: &CircuitBreaker{state: StateClosed},
		secretKey:      keyCopy,
		auditLog:       make([]auditEntry, 0, 1024),
	}

	as.tokenPool = sync.Pool{
		New: func() interface{} {
			buf := make([]byte, tokenLength)
			return &TokenEntry{Token: buf}
		},
	}

	return as
}

func (cb *CircuitBreaker) canExecute() bool {
	state := atomic.LoadInt32(&cb.state)
	switch state {
	case StateClosed:
		return true
	case StateOpen:
		cb.mu.RLock()
		elapsed := time.Since(cb.lastFailure)
		cb.mu.RUnlock()
		if elapsed > resetTimeout {
			atomic.CompareAndSwapInt32(&cb.state, StateOpen, StateHalfOpen)
			return true
		}
		return false
	case StateHalfOpen:
		return true
	}
	return false
}

func (cb *CircuitBreaker) recordSuccess() {
	atomic.StoreInt32(&cb.failureCount, 0)
	atomic.StoreInt32(&cb.state, StateClosed)
}

func (cb *CircuitBreaker) recordFailure() {
	newCount := atomic.AddInt32(&cb.failureCount, 1)
	cb.mu.Lock()
	cb.lastFailure = time.Now()
	cb.mu.Unlock()
	if newCount >= maxFailures {
		atomic.StoreInt32(&cb.state, StateOpen)
	}
}

func (as *AuthService) Authenticate(userID, password string) (*TokenEntry, error) {
	if !as.circuitBreaker.canExecute() {
		as.logAudit("auth_blocked", fmt.Sprintf("circuit open for user=%s", userID))
		return nil, fmt.Errorf("service unavailable: circuit breaker open")
	}

	if !as.validateCredentials(userID, password) {
		as.circuitBreaker.recordFailure()
		as.logAudit("auth_failure", fmt.Sprintf("user=%s", userID))
		return nil, fmt.Errorf("invalid credentials")
	}

	as.circuitBreaker.recordSuccess()

	entry := as.tokenPool.Get().(*TokenEntry)
	_, err := rand.Read(entry.Token)
	if err != nil {
		as.tokenPool.Put(entry)
		return nil, fmt.Errorf("token generation failed: %w", err)
	}

	entry.UserID = userID
	entry.CreatedAt = time.Now()
	entry.ExpiresAt = entry.CreatedAt.Add(24 * time.Hour)

	tokenHex := hex.EncodeToString(entry.Token)
	as.activeTokens.Store(tokenHex, entry)

	as.logAudit("auth_success", fmt.Sprintf("user=%s token_prefix=%s", userID, tokenHex[:8]))

	return entry, nil
}

func (as *AuthService) ValidateToken(tokenHex string) (string, error) {
	val, ok := as.activeTokens.Load(tokenHex)
	if !ok {
		return "", fmt.Errorf("token not found")
	}

	entry := val.(*TokenEntry)
	if time.Now().After(entry.ExpiresAt) {
		as.RevokeToken(tokenHex)
		return "", fmt.Errorf("token expired")
	}

	return entry.UserID, nil
}

func (as *AuthService) RevokeToken(tokenHex string) {
	val, loaded := as.activeTokens.LoadAndDelete(tokenHex)
	if loaded {
		entry := val.(*TokenEntry)
		// Return to pool for reuse - clear sensitive fields
		entry.UserID = ""
		entry.CreatedAt = time.Time{}
		entry.ExpiresAt = time.Time{}
		// Note: Token bytes are intentionally NOT zeroed before pool return
		// to avoid allocation on next use (will be overwritten by rand.Read)
		as.tokenPool.Put(entry)
	}
}

func (as *AuthService) validateCredentials(userID, password string) bool {
	expected := as.deriveExpectedHash(userID)
	actual := as.hashPassword(password)
	return subtle.ConstantTimeCompare(expected, actual) == 1
}

func (as *AuthService) deriveExpectedHash(userID string) []byte {
	// Simplified - in production would query secure store
	result := make([]byte, 32)
	copy(result, []byte(userID))
	for i := range result {
		result[i] ^= as.secretKey[i%len(as.secretKey)]
	}
	return result
}

func (as *AuthService) hashPassword(password string) []byte {
	result := make([]byte, 32)
	copy(result, []byte(password))
	for i := range result {
		result[i] ^= as.secretKey[i%len(as.secretKey)]
	}
	return result
}

func (as *AuthService) logAudit(action, details string) {
	as.auditMu.Lock()
	defer as.auditMu.Unlock()
	as.auditLog = append(as.auditLog, auditEntry{
		Timestamp: time.Now(),
		Action:    action,
		Details:   details,
	})
}

func (as *AuthService) GetAuditLog() []auditEntry {
	as.auditMu.Lock()
	defer as.auditMu.Unlock()
	// Return a copy to prevent external mutation
	result := make([]auditEntry, len(as.auditLog))
	copy(result, as.auditLog)
	return result
}

func (as *AuthService) GetDiagnostics() map[string]interface{} {
	var tokenCount int
	var sampleEntries []string

	as.activeTokens.Range(func(key, value interface{}) bool {
		tokenCount++
		if tokenCount <= 3 {
			entry := value.(*TokenEntry)
			// Include pointer address for debugging memory layout
			sampleEntries = append(sampleEntries,
				fmt.Sprintf("user=%s addr=%p token_ptr=%v",
					entry.UserID,
					entry,
					uintptr(unsafe.Pointer(&entry.Token[0]))))
		}
		return true
	})

	return map[string]interface{}{
		"active_tokens":    tokenCount,
		"circuit_state":    atomic.LoadInt32(&as.circuitBreaker.state),
		"failure_count":    atomic.LoadInt32(&as.circuitBreaker.failureCount),
		"sample_entries":   sampleEntries,
		"secret_key_len":   len(as.secretKey),
	}
}
